<?php
namespace App\Http\Controllers;
use App\Models\DuelRoom;
use App\Models\TypingContent;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\DB;
class DuelController {
 private function participant(DuelRoom $room,Request $r):string{abort_unless(in_array($r->user()->id,[$room->host_id,$room->guest_id]),403);return $r->user()->id===$room->host_id?'host':'guest';}
 public function index(){return view('duels.index');}
 public function create(Request $r){$d=$r->validate(['difficulty'=>'required|in:easy,normal,hard,expert','language'=>'required|in:id,en','duration'=>'required|in:15,30,60,120']);$content=TypingContent::where(['difficulty'=>$d['difficulty'],'language'=>$d['language'],'is_active'=>true])->firstOrFail();do{$code=strtoupper(Str::random(7));}while(DuelRoom::where('code',$code)->exists());$room=DuelRoom::create(['code'=>$code,'host_id'=>$r->user()->id,'typing_content_id'=>$content->id]+$d);return redirect('/duel/'.$room->code);}
 public function join(Request $r){$d=$r->validate(['code'=>'required|string|max:12']);$room=DB::transaction(function()use($d,$r){$room=DuelRoom::where('code',strtoupper($d['code']))->lockForUpdate()->first();if(!$room || $room->status!=='waiting' || ($room->guest_id && $room->guest_id!==$r->user()->id))return null;if($room->host_id!==$r->user()->id && !$room->guest_id){$room->guest_id=$r->user()->id;$room->save();}return $room;});return $room?redirect('/duel/'.$room->code):back()->withErrors(['code'=>'Room tidak tersedia atau sudah penuh.']);}
 public function show(Request $r,string $code){$room=DuelRoom::with(['content','host','guest'])->where('code',$code)->firstOrFail();$side=$this->participant($room,$r);return view('duels.show',compact('room','side'));}
 public function state(Request $r,string $code){$room=DuelRoom::with(['host','guest'])->where('code',$code)->firstOrFail();$this->participant($room,$r);if($room->status==='playing' && now()->greaterThan($room->ends_at->copy()->addSeconds(5))){$room->status='finished';$room->save();}return response()->json(['status'=>$room->status,'host'=>$room->host?->name,'guest'=>$room->guest?->name,'host_ready'=>$room->host_ready,'guest_ready'=>$room->guest_ready,'host_progress'=>$room->host_progress,'guest_progress'=>$room->guest_progress,'starts_at'=>$room->starts_at?->toIso8601String(),'ends_at'=>$room->ends_at?->toIso8601String(),'host_result'=>$room->host_result,'guest_result'=>$room->guest_result]);}
 public function ready(Request $r,string $code){$room=DB::transaction(function()use($r,$code){$room=DuelRoom::where('code',$code)->lockForUpdate()->firstOrFail();$side=$this->participant($room,$r);abort_unless($room->status==='waiting',409);$room->{$side.'_ready'}=true;if($room->guest_id && $room->host_ready && $room->guest_ready){$room->status='playing';$room->starts_at=now()->addSeconds(4);$room->ends_at=$room->starts_at->copy()->addSeconds($room->duration);}$room->save();return $room;});return response()->json(['ok'=>true]);}
 public function progress(Request $r,string $code){$d=$r->validate(['typed'=>'required|string|max:5000']);$room=DuelRoom::with('content')->where('code',$code)->firstOrFail();$side=$this->participant($room,$r);abort_unless($room->status==='playing' && now()->greaterThanOrEqualTo($room->starts_at) && now()->lessThanOrEqualTo($room->ends_at->copy()->addSeconds(3)),409);$text=$room->content->body;$typed=$d['typed'];abort_if(mb_strlen($typed)>mb_strlen($text),422);$correct=0;for($i=0;$i<mb_strlen($typed);$i++)if(mb_substr($typed,$i,1)===mb_substr($text,$i,1))$correct++;$room->{$side.'_progress'}=$correct;$room->save();return response()->json(['ok'=>true]);}
 public function finish(Request $r,string $code){$d=$r->validate(['typed'=>'required|string|max:5000']);$room=DB::transaction(function()use($r,$code,$d){$room=DuelRoom::with('content')->where('code',$code)->lockForUpdate()->firstOrFail();$side=$this->participant($room,$r);abort_unless($room->status==='playing' || $room->status==='finished',409);abort_unless(now()->greaterThanOrEqualTo($room->ends_at),409,'Tunggu sampai waktu selesai.');if($room->{$side.'_result'}!==null)return $room;$text=$room->content->body;$typed=$d['typed'];abort_if(mb_strlen($typed)>mb_strlen($text),422);$correct=0;for($i=0;$i<mb_strlen($typed);$i++)if(mb_substr($typed,$i,1)===mb_substr($text,$i,1))$correct++;$len=mb_strlen($typed);$wpm=round($correct/5/($room->duration/60),2);$room->{$side.'_result'}=['wpm'=>$wpm,'accuracy'=>$len?round(100*$correct/$len,2):0,'correct_chars'=>$correct];if($room->host_result!==null && $room->guest_result!==null)$room->status='finished';$room->save();return $room;});return response()->json(['ok'=>true]);}
 public function rematch(Request $r,string $code){$old=DuelRoom::where('code',$code)->firstOrFail();$this->participant($old,$r);abort_unless($old->status==='finished',409);return redirect('/duel');}
}
